<script setup lang="ts">
import { computed,onDeactivated,onBeforeUnmount,ref,watch } from 'vue'
import { allowsBlankServiceKey,type ServiceForm } from '../../hooks/unified-service'
import { capabilityNames,defaultRerankUrl,searchProtocolNames,searchProtocolUrls,searchDepthNames,type SearchProtocol } from '../../types'
import { suggestThinkingProtocol,thinkingModeNames,thinkingProtocolNames,type ThinkingMode,type ThinkingProtocol } from '../../thinking'
import StatusTag from '../ui/StatusTag.vue'
import Panel from './ServicesPanel.vue'
import Button from '../ui/Button.vue'
import Field from '../ui/Field.vue'
import Select from '../ui/Select.vue'
import Switch from '../ui/Switch.vue'
import FormField from './FormField.vue'
const props=defineProps<{value:ServiceForm;busy:boolean;saved:boolean;active:boolean;onSave:(value:ServiceForm,test?:boolean)=>Promise<boolean>}>(),emit=defineEmits<{remove:[]}>()
const editing=ref(!props.saved),validation=ref(''),draft=ref({...props.value}),form=ref<HTMLFormElement|null>(null)
watch(()=>props.value,value=>{draft.value={...value}})
watch(()=>props.active,active=>{if(!active)draft.value.apiKey=undefined})
onDeactivated(()=>{draft.value.apiKey=undefined})
onBeforeUnmount(()=>{draft.value.apiKey=undefined})
const address=computed(()=>{try{const url=new URL(props.value.url);return {text:`${url.origin}${url.pathname}`,host:url.hostname}}catch{return {text:'未配置有效接口地址',host:'未配置'}}})
const changedUrl=computed(()=>props.saved&&(draft.value.url.trim()!==props.value.url||draft.value.kind!==props.value.kind||(draft.value.kind==='web-search'&&(draft.value.searchProtocol??'tavily')!==(props.value.searchProtocol??'tavily'))))
const changed=computed(()=>JSON.stringify(draft.value)!==JSON.stringify(props.value))
const protocol=computed(()=>draft.value.searchProtocol??'tavily')
function selectProtocol(value:unknown){const next=value as SearchProtocol;const old=protocol.value;draft.value={...draft.value,searchProtocol:next,url:!draft.value.url.trim()||draft.value.url.trim()===searchProtocolUrls[old]?searchProtocolUrls[next]:draft.value.url,apiKey:undefined}}
function mode(value:unknown){draft.value.thinkingMode=value as ThinkingMode;if(draft.value.thinkingProtocol==='none'||!draft.value.thinkingProtocol)draft.value.thinkingProtocol=suggestThinkingProtocol(draft.value.url)}
async function save(test=false){if(props.busy||!form.value?.reportValidity())return;validation.value='';if(draft.value.kind==='llm'&&draft.value.thinkingMode!=='default'&&(!draft.value.thinkingProtocol||draft.value.thinkingProtocol==='none')){validation.value='请选择模型支持的思考参数协议。';return}const ok=await props.onSave({...draft.value},test);if(ok&&!test)draft.value.apiKey=undefined}
const options=(map:Record<string,string>)=>Object.entries(map).map(([value,label])=>({value,label}))
</script>
<template><Panel :title="value.name||`新${capabilityNames[value.kind]}`" class="reveal"><template #tools><StatusTag :status="saved&&value.enabled" :on="'已启用'" :off="saved?'已停用':'未保存'"/></template><template v-if="!editing"><div class="kv-grid"><div class="kv"><div class="kv-label">服务类型</div><div class="kv-value">{{capabilityNames[value.kind]}}</div></div><div class="kv" v-if="value.kind!=='web-search'"><div class="kv-label">模型</div><div class="kv-value">{{value.model}}</div></div><div class="kv"><div class="kv-label">接口地址</div><div class="kv-value">{{address.text}}</div></div><div class="kv"><div class="kv-label">域名 / 服务商</div><div class="kv-value">{{address.host}}</div></div><div class="kv"><div class="kv-label">API Key</div><div class="kv-value">{{value.hasApiKey?'已保存':'未配置'}}</div></div><div class="kv" v-if="value.kind==='llm'"><div class="kv-label">思考模式</div><div class="kv-value">{{thinkingModeNames[value.thinkingMode??'default']}}{{value.thinkingMode&&value.thinkingMode!=='default'?` · ${thinkingProtocolNames[value.thinkingProtocol??'none']}`:''}}</div></div><div class="kv" v-if="value.kind==='llm'"><div class="kv-label">最大输出</div><div class="kv-value">{{value.maxOutputTokens.toLocaleString()}} Tokens</div></div><div class="kv" v-if="value.kind==='embedding'"><div class="kv-label">向量维度</div><div class="kv-value">{{value.dimensions}} 维</div></div><div class="kv" v-if="value.kind==='web-search'"><div class="kv-label">搜索供应商</div><div class="kv-value">{{searchProtocolNames[protocol]}}</div></div><div class="kv" v-if="value.kind==='rerank'"><div class="kv-label">超时</div><div class="kv-value">{{value.timeoutMs}} ms</div></div><template v-if="value.kind==='web-search'"><div class="kv"><div class="kv-label">保留网页数量（topK）</div><div class="kv-value">{{value.topK}} 条</div></div><div class="kv"><div class="kv-label">超时</div><div class="kv-value">{{value.timeoutMs}} ms</div></div><div class="kv" v-if="protocol==='tavily'"><div class="kv-label">搜索深度</div><div class="kv-value">{{searchDepthNames[value.searchDepth]}}</div></div><div class="kv" v-if="protocol==='tavily'"><div class="kv-label">包含摘要答案</div><div class="kv-value">{{value.includeAnswer==='advanced'?'高级摘要':value.includeAnswer==='basic'?'基础摘要':'不包含'}}</div></div></template></div><div class="page-actions"><Button :disabled="busy" @click="editing=true">编辑配置</Button><Button :disabled="busy||!value.enabled" @click="onSave(value,true)">测试连接</Button><Button :disabled="busy" @click="onSave({...value,enabled:!value.enabled})">{{value.enabled?'停用':'启用'}}</Button><Button variant="text" danger :disabled="busy" @click="emit('remove')">删除</Button></div></template><form v-else ref="form" class="stack" :aria-label="`模型服务 ${value.name||'新服务'}`" @submit.prevent="save()"><fieldset class="form-grid" :disabled="busy"><FormField v-model="draft.name" label="显示名称" required maxlength="100"/><FormField v-if="value.kind!=='web-search'" v-model="draft.model" label="模型名称" required maxlength="200"/><FormField v-model="draft.url" class="span-2" label="接口地址" type="url" required maxlength="2048"/><p class="field-hint span-2">{{value.kind==='llm'?'填写完整 Chat Completions 地址，以 /chat/completions 结尾。':value.kind==='asr'?'填写 Fun-ASR WebSocket 地址。':value.kind==='embedding'?'填写完整 Embeddings 地址，以 /embeddings 结尾，向量固定 1024 维。':value.kind==='rerank'?`填写百炼原生重排序完整 HTTPS 地址，例如 ${defaultRerankUrl}，不会自动补全路径。`:`填写 ${protocol==='deepseek'?'DeepSeek 完整 HTTPS 地址，以 /v1/tools/search 结尾':'Tavily 完整 HTTPS Search 地址，以 /search 结尾'}。`}}</p><FormField v-model="draft.apiKey" label="API Key" type="password" autocomplete="new-password" :required="changedUrl||(!allowsBlankServiceKey(draft)&&!value.hasApiKey&&(value.kind!=='rerank'||draft.enabled))" :placeholder="value.hasApiKey?'已保存，留空保留':'请输入 API Key'"/><FormField v-if="value.kind==='llm'" v-model="draft.maxOutputTokens" label="最大输出 Token" type="number" min="1" max="32768" required/><template v-if="value.kind==='llm'"><Field label="思考模式"><Select :model-value="draft.thinkingMode??'default'" :options="options(thinkingModeNames)" @update:model-value="mode"/></Field><Field v-if="draft.thinkingMode!=='default'" label="思考参数协议"><Select :model-value="draft.thinkingProtocol==='none'?'':draft.thinkingProtocol" :options="options(thinkingProtocolNames).filter(item=>item.value!=='none')" placeholder="请选择模型支持的协议" @update:model-value="draft.thinkingProtocol=$event as ThinkingProtocol"/></Field><p class="field-hint span-2">实时面试建议关闭思考。开启可能增加等待时间和 Token 消耗；跟随默认不发送开关参数。请确认模型支持所选协议。</p></template><template v-if="value.kind==='web-search'"><Field label="搜索供应商"><Select :model-value="protocol" :options="options(searchProtocolNames)" @update:model-value="selectProtocol"/></Field><FormField v-model="draft.topK" label="保留网页数量（topK）" type="number" min="1" max="20" required/><Field v-if="protocol==='tavily'" label="搜索深度"><Select v-model="draft.searchDepth" :options="options(searchDepthNames)"/></Field><FormField v-model="draft.timeoutMs" label="超时（毫秒）" type="number" min="1000" max="30000" required/><Field v-if="protocol==='tavily'" label="包含摘要答案"><Select v-model="draft.includeAnswer" :options="[{value:'none',label:'不包含'},{value:'basic',label:'基础摘要'},{value:'advanced',label:'高级摘要'}]"/></Field><p class="field-hint span-2">联网搜索与 RAG 并行，搜索失败继续回答。更换供应商后须重新填写 API Key；自定义接口地址保留，请核对完整路径。</p></template><template v-if="value.kind==='rerank'"><FormField v-model="draft.timeoutMs" label="重排序超时（毫秒）" type="number" min="300" max="5000" required/><p class="field-hint span-2">使用百炼原生重排序协议，建议模型 qwen3-rerank。只处理 RRF 候选池，异常时按 RRF 顺序继续回答；保存下一次检索请求生效。</p></template><FormField v-if="value.kind==='embedding'" label="向量维度" :model-value="1024" type="number" readonly/><Switch v-if="!saved" v-model="draft.enabled" label="启用，保存后供平台使用"/></fieldset><p v-if="validation" class="field-error" role="alert">{{validation}}</p><div class="page-actions"><Button v-if="saved" :disabled="busy" @click="draft={...value};editing=false">取消编辑</Button><Button type="submit" variant="primary" :disabled="busy">保存</Button><Button :disabled="busy||!draft.enabled" @click="save(true)">测试连接</Button><Button v-if="saved" :disabled="busy||changed" @click="onSave({...value,enabled:!value.enabled})">{{value.enabled?'停用':'启用'}}</Button><Button variant="text" danger :disabled="busy" @click="emit('remove')">删除</Button></div></form></Panel></template>
